PRAGMA foreign_keys=ON; CREATE TABLE t8(a, b, c, d, e, FOREIGN KEY(c, d) REFERENCES t8(a, b)); CREATE UNIQUE INDEX t8i1 ON t8(a, b); CREATE UNIQUE INDEX t8i2 ON t8(c); INSERT INTO t8 VALUES(1, 1, 1, 1, 1); CREATE TABLE t8_log(seq INTEGER PRIMARY KEY, old_d, new_d, old_e, new_e); CREATE TRIGGER t8_log_update AFTER UPDATE ON t8 BEGIN INSERT INTO t8_log(old_d,new_d,old_e,new_e) VALUES(OLD.d,NEW.d,OLD.e,NEW.e); END;